with batch as(select value e from jsonb_array_elements($el6$[
{"slug":"double-dumbbell-suitcase-carry","name":"Double Dumbbell Suitcase Carry","family":"loaded_carry","pattern":"carry","role":"secondary","primaryMuscles":["core"],"secondaryMuscles":["shoulders","back","glutes"],"requiredEquipment":["dumbbells"],"skill":"new","fatigueCost":2,"progressionSuitability":5,"repRange":[20,60],"instructions":["Stand between two dumbbells, hinge to grip them, and establish a clear walking path.","Walk with quiet steps, long arms, and the rib cage stacked over the pelvis.","Stop under control and hinge to return both dumbbells without dropping them."],"cues":["Walk tall.","Keep both weights quiet."],"mistakes":["Rushing the turn.","Letting the weights pull the shoulders forward."],"cautionTags":["reported_back_or_shoulder_discomfort"]},
{"slug":"dumbbell-march-carry","name":"Dumbbell March Carry","family":"loaded_carry","pattern":"carry","role":"accessory","primaryMuscles":["core"],"secondaryMuscles":["glutes","shoulders"],"requiredEquipment":["dumbbells"],"skill":"beginner","fatigueCost":2,"progressionSuitability":4,"repRange":[10,30],"instructions":["Hold two dumbbells at the sides and stand with space around you.","March slowly, lifting one foot at a time without leaning or rushing.","Finish balanced, then return the weights with a controlled hinge."],"cues":["Own each step.","Keep the belt line level."],"mistakes":["Leaning away from the stance leg.","Using a load that shortens balance time."],"cautionTags":["reported_back_or_hip_discomfort"]},
{"slug":"band-resisted-march","name":"Band-Resisted March","family":"resisted_carry","pattern":"carry","role":"accessory","primaryMuscles":["core","glutes"],"secondaryMuscles":["quadriceps"],"requiredEquipment":["bands"],"skill":"new","fatigueCost":1,"progressionSuitability":3,"repRange":[10,30],"instructions":["Secure a band behind the waist and step forward until tension is light and steady.","March in place or forward with a tall torso and deliberate foot contacts.","Walk backward carefully to remove band tension before exiting."],"cues":["Stay tall against the pull.","Place each foot quietly."],"mistakes":["Using an insecure anchor.","Leaning far forward to overpower the band."],"cautionTags":["reported_balance_or_hip_discomfort"]},
{"slug":"front-rack-dumbbell-march","name":"Front-Rack Dumbbell March","family":"front_rack_carry","pattern":"carry","role":"secondary","primaryMuscles":["core"],"secondaryMuscles":["shoulders","quadriceps"],"requiredEquipment":["dumbbells"],"skill":"beginner","fatigueCost":2,"progressionSuitability":4,"repRange":[10,30],"instructions":["Bring two dumbbells to a comfortable front-rack position and clear the floor area.","March without arching the low back or allowing the dumbbells to drift.","Lower both dumbbells under control after regaining a stable stance."],"cues":["Ribs over pelvis.","Breathe behind the brace."],"mistakes":["Holding the breath for the entire set.","Letting the elbows or torso collapse."],"cautionTags":["reported_back_or_shoulder_discomfort"]},
{"slug":"single-arm-front-rack-carry","name":"Single-Arm Front-Rack Carry","family":"front_rack_carry","pattern":"carry","role":"secondary","primaryMuscles":["core"],"secondaryMuscles":["shoulders","back"],"requiredEquipment":["dumbbells"],"skill":"beginner","fatigueCost":2,"progressionSuitability":4,"repRange":[20,60],"instructions":["Hold one dumbbell at the shoulder and choose a clear walking lane.","Walk without rotating or leaning away from the loaded side.","Stop, lower the dumbbell safely, and repeat evenly on the other side."],"cues":["Stay square.","Keep the loaded wrist stacked."],"mistakes":["Leaning to counterbalance.","Turning before controlling momentum."],"cautionTags":["reported_back_or_shoulder_discomfort"]},
{"slug":"band-overhead-march","name":"Band Overhead March","family":"overhead_carry","pattern":"carry","role":"accessory","primaryMuscles":["core","shoulders"],"secondaryMuscles":["glutes"],"requiredEquipment":["bands"],"skill":"intermediate","fatigueCost":2,"progressionSuitability":3,"repRange":[10,25],"instructions":["Stand on a light band and press both handles overhead to a comfortable position.","March slowly while keeping the arms steady and the torso stacked.","Stop marching before lowering the handles under control."],"cues":["Reach tall without arching.","Use slow steps."],"mistakes":["Using band tension that pulls the arms out of position.","Continuing through shoulder discomfort."],"cautionTags":["reported_shoulder_or_back_discomfort"]},
{"slug":"towel-grip-dumbbell-carry","name":"Towel-Grip Dumbbell Carry","family":"grip_carry","pattern":"carry","role":"accessory","primaryMuscles":["core"],"secondaryMuscles":["back","shoulders"],"requiredEquipment":["dumbbells"],"skill":"intermediate","fatigueCost":2,"progressionSuitability":3,"repRange":[15,45],"instructions":["Loop sturdy towels securely around light dumbbell handles and verify both grips.","Walk a short clear path with the arms long and the towels controlled.","Set the weights down before grip failure changes posture."],"cues":["Crush the towels.","End before the grip slips."],"mistakes":["Using damaged towels.","Walking after the grip begins to open."],"cautionTags":["reported_wrist_or_elbow_discomfort"]},
{"slug":"bear-hug-dumbbell-carry","name":"Bear-Hug Dumbbell Carry","family":"bear_hug_carry","pattern":"carry","role":"secondary","primaryMuscles":["core"],"secondaryMuscles":["chest","biceps","back"],"requiredEquipment":["dumbbells"],"skill":"beginner","fatigueCost":2,"progressionSuitability":3,"repRange":[15,45],"instructions":["Hold one dumbbell vertically against the torso with both hands and clear the path.","Walk with normal breathing and the load held securely against the body.","Stop and place the dumbbell down before the hands or posture shift."],"cues":["Hug the load securely.","Keep normal breathing."],"mistakes":["Obscuring the walking path with the load.","Leaning backward to support excess weight."],"cautionTags":["reported_back_or_elbow_discomfort"]},
{"slug":"band-assisted-chin-up","name":"Band-Assisted Chin-Up","family":"chin_up","pattern":"vertical_pull","role":"primary","primaryMuscles":["back","biceps"],"secondaryMuscles":["core"],"requiredEquipment":["bands"],"skill":"beginner","fatigueCost":3,"progressionSuitability":4,"repRange":[4,12],"instructions":["Secure a band to a rated pull-up bar and place a foot or knee into it carefully.","Pull the chest upward with the shoulders controlled, then lower to long arms.","Remove the foot or knee only after both hands and body are stable."],"cues":["Drive elbows down.","Control the band return."],"mistakes":["Using a damaged or insecure band.","Dropping quickly into the bottom."],"cautionTags":["reported_shoulder_or_elbow_discomfort"]},
{"slug":"band-assisted-neutral-pull-up","name":"Band-Assisted Neutral-Grip Pull-Up","family":"pull_up","pattern":"vertical_pull","role":"primary","primaryMuscles":["back","biceps"],"secondaryMuscles":["core"],"requiredEquipment":["bands"],"skill":"beginner","fatigueCost":3,"progressionSuitability":4,"repRange":[4,12],"instructions":["Attach a band to rated neutral handles and enter the assistance position carefully.","Pull with the elbows toward the ribs and lower without losing shoulder control.","Exit the band only after returning to a stable supported position."],"cues":["Keep the grip neutral.","Finish with control."],"mistakes":["Swinging to clear the sticking point.","Letting the band snap during exit."],"cautionTags":["reported_shoulder_or_elbow_discomfort"]},
{"slug":"seated-band-lat-pulldown","name":"Seated Band Lat Pulldown","family":"vertical_pull","pattern":"vertical_pull","role":"secondary","primaryMuscles":["back"],"secondaryMuscles":["biceps"],"requiredEquipment":["bands"],"skill":"new","fatigueCost":1,"progressionSuitability":3,"repRange":[10,25],"instructions":["Secure a band overhead and sit where both sides begin with equal tension.","Pull the hands toward the upper chest while the torso stays tall.","Return the arms overhead slowly without allowing the anchor to shift."],"cues":["Pull elbows toward pockets.","Keep the neck relaxed."],"mistakes":["Using an unverified anchor.","Leaning backward to create range."],"cautionTags":["reported_shoulder_discomfort"]},
{"slug":"half-kneeling-single-arm-band-pulldown","name":"Half-Kneeling Single-Arm Band Pulldown","family":"vertical_pull","pattern":"vertical_pull","role":"secondary","primaryMuscles":["back"],"secondaryMuscles":["biceps","core"],"requiredEquipment":["bands"],"skill":"beginner","fatigueCost":1,"progressionSuitability":3,"repRange":[10,20],"instructions":["Anchor a band overhead and take a stable half-kneeling stance.","Pull one elbow toward the side while resisting torso rotation.","Return slowly and complete equal work on the other side."],"cues":["Stay square.","Move the elbow, not the torso."],"mistakes":["Arching to finish the pull.","Using uneven kneeling support."],"cautionTags":["reported_shoulder_or_knee_discomfort"]},
{"slug":"eccentric-chin-up","name":"Eccentric Chin-Up","family":"chin_up","pattern":"vertical_pull","role":"secondary","primaryMuscles":["back","biceps"],"secondaryMuscles":["core"],"requiredEquipment":["bodyweight","bench"],"skill":"intermediate","fatigueCost":3,"progressionSuitability":3,"repRange":[3,8],"instructions":["Use a stable step to begin at the top of a chin-up with both hands secure.","Lower for three to five seconds while keeping the shoulders controlled.","Step back to the top rather than jumping into the next repetition."],"cues":["Lower evenly.","Keep the ribs quiet."],"mistakes":["Using an unstable step.","Dropping through the last part of the repetition."],"cautionTags":["reported_shoulder_or_elbow_discomfort"]},
{"slug":"scapular-pull-up","name":"Scapular Pull-Up","family":"scapular_pull","pattern":"vertical_pull","role":"accessory","primaryMuscles":["back"],"secondaryMuscles":["shoulders","core"],"requiredEquipment":["bodyweight"],"skill":"beginner","fatigueCost":1,"progressionSuitability":3,"repRange":[6,15],"instructions":["Hang from a rated bar with a grip and shoulder position that feel controlled.","Without bending the elbows, draw the shoulders down and slightly lift the body.","Return to the starting hang slowly and stop before grip control is lost."],"cues":["Keep elbows long.","Move only through the shoulder blades."],"mistakes":["Turning the movement into a partial pull-up.","Forcing an uncomfortable dead hang."],"cautionTags":["reported_shoulder_discomfort"]},
{"slug":"tall-kneeling-band-overhead-press","name":"Tall-Kneeling Band Overhead Press","family":"overhead_press","pattern":"vertical_push","role":"secondary","primaryMuscles":["shoulders","triceps"],"secondaryMuscles":["core"],"requiredEquipment":["bands"],"skill":"beginner","fatigueCost":2,"progressionSuitability":3,"repRange":[8,20],"instructions":["Kneel on the center of a band and hold the handles at shoulder level.","Press overhead without leaning back, then lower to the same start position.","Release band tension only after both hands are controlled."],"cues":["Squeeze the glutes.","Press without rib flare."],"mistakes":["Kneeling on an uneven surface.","Choosing tension that changes the press path."],"cautionTags":["reported_shoulder_or_knee_discomfort"]},
{"slug":"half-kneeling-single-arm-band-press","name":"Half-Kneeling Single-Arm Band Overhead Press","family":"overhead_press","pattern":"vertical_push","role":"secondary","primaryMuscles":["shoulders","triceps"],"secondaryMuscles":["core"],"requiredEquipment":["bands"],"skill":"beginner","fatigueCost":2,"progressionSuitability":3,"repRange":[8,20],"instructions":["Secure a band beneath the rear knee or foot and establish a stable half-kneeling stance.","Press one hand overhead while keeping the trunk square.","Lower slowly and change sides only after removing band tension."],"cues":["Stay stacked.","Reach overhead smoothly."],"mistakes":["Twisting toward the pressing arm.","Allowing the band to pull the wrist back."],"cautionTags":["reported_shoulder_or_knee_discomfort"]},
{"slug":"single-arm-dumbbell-z-press","name":"Single-Arm Dumbbell Z Press","family":"overhead_press","pattern":"vertical_push","role":"secondary","primaryMuscles":["shoulders","triceps"],"secondaryMuscles":["core"],"requiredEquipment":["dumbbells"],"skill":"intermediate","fatigueCost":2,"progressionSuitability":3,"repRange":[6,15],"instructions":["Sit on the floor with legs extended and hold one dumbbell at the shoulder.","Press overhead without leaning or rotating, then lower under control.","Return the dumbbell to the floor safely before changing sides."],"cues":["Sit tall.","Stay square through the press."],"mistakes":["Forcing a seated position without adequate mobility.","Leaning away from the load."],"cautionTags":["reported_back_or_shoulder_discomfort"]},
{"slug":"dumbbell-thruster","name":"Dumbbell Thruster","family":"push_press","pattern":"vertical_push","role":"secondary","primaryMuscles":["quadriceps","glutes","shoulders"],"secondaryMuscles":["triceps","core"],"requiredEquipment":["dumbbells"],"skill":"intermediate","fatigueCost":4,"progressionSuitability":3,"repRange":[6,15],"instructions":["Hold two dumbbells at the shoulders and establish a stable squat stance.","Squat under control, then stand and continue the momentum into an overhead press.","Lower the dumbbells to the shoulders before beginning the next squat."],"cues":["Drive through the legs.","Finish stacked overhead."],"mistakes":["Pressing before the legs extend.","Using fatigue to justify an unstable overhead position."],"cautionTags":["reported_knee_back_or_shoulder_discomfort"]}
]$el6$::jsonb))
insert into public.exercises(slug,name,status,family,movement_pattern,exercise_role,primary_muscles,secondary_muscles,required_equipment,skill_level,fatigue_cost,progression_suitability,rep_min,rep_max,education,caution_tags,content_version,license_key,review_status)
select e->>'slug',e->>'name','production',e->>'family',e->>'pattern',e->>'role',array(select jsonb_array_elements_text(e->'primaryMuscles')),array(select jsonb_array_elements_text(e->'secondaryMuscles')),array(select jsonb_array_elements_text(e->'requiredEquipment')),e->>'skill',(e->>'fatigueCost')::smallint,(e->>'progressionSuitability')::smallint,(e->'repRange'->>0)::smallint,(e->'repRange'->>1)::smallint,jsonb_build_object('setup',jsonb_build_array(e->'instructions'->>0),'execution',jsonb_build_array(e->'instructions'->>1,e->'instructions'->>2),'cues',e->'cues','mistakes',e->'mistakes'),array(select jsonb_array_elements_text(e->'cautionTags')),'1.0.0','STHENO_ORIGINAL','reviewed' from batch on conflict(slug) do nothing;
